import { motion } from 'framer-motion';
import { useScrollReveal } from '../hooks/useScrollReveal';
import { personalInfo, quotes } from '../data/portfolio';
import { useState, useEffect } from 'react';

export default function About() {
  const [ref, isVisible] = useScrollReveal(0.2);
  const [quote, setQuote] = useState('');

  useEffect(() => {
    setQuote(quotes[Math.floor(Math.random() * quotes.length)]);
  }, []);

  return (
    <section id="about" className="section-padding relative">
      <div className="absolute inset-0 radial-gradient" />
      <div ref={ref} className="relative max-w-7xl mx-auto">
        {/* Section header */}
        <motion.div
          initial={{ opacity: 0, y: 40 }}
          animate={isVisible ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.6 }}
          className="mb-16"
        >
          <p className="text-cyan-400 font-medium mb-2 tracking-wider uppercase text-sm">Get to know me</p>
          <h2 className="text-4xl sm:text-5xl font-bold text-white">
            About <span className="gradient-text">Me</span>
          </h2>
        </motion.div>

        <div className="grid lg:grid-cols-2 gap-12 lg:gap-20 items-center">
          {/* Image side */}
          <motion.div
            initial={{ opacity: 0, x: -60 }}
            animate={isVisible ? { opacity: 1, x: 0 } : {}}
            transition={{ duration: 0.7, delay: 0.2 }}
            className="relative"
          >
            <div className="relative rounded-2xl overflow-hidden glow-border">
              <div className="aspect-square bg-gradient-to-br from-dark-700 to-dark-800 rounded-2xl flex items-center justify-center p-8">
                <img
                  src={personalInfo.profileImage}
                  alt="Chanakya Sharma"
                  className="w-full h-full object-cover rounded-xl"
                />
              </div>
            </div>
            {/* Floating quote card */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={isVisible ? { opacity: 1, y: 0 } : {}}
              transition={{ delay: 0.8 }}
              className="absolute -bottom-6 -right-4 sm:right-[-2rem] max-w-xs glass rounded-xl p-4 shadow-xl"
            >
              <p className="text-sm text-gray-300 italic leading-relaxed">"{quote}"</p>
            </motion.div>
          </motion.div>

          {/* Content side */}
          <motion.div
            initial={{ opacity: 0, x: 60 }}
            animate={isVisible ? { opacity: 1, x: 0 } : {}}
            transition={{ duration: 0.7, delay: 0.3 }}
          >
            <h3 className="text-2xl font-bold text-white mb-6">
              Full Stack Engineer who ships production systems at scale
            </h3>
            <p className="text-gray-400 leading-relaxed mb-6 text-lg">
              {personalInfo.bio}
            </p>
            <p className="text-gray-400 leading-relaxed mb-8">
              I've built SaaS platforms from scratch, decomposed monoliths into microservices on AWS,
              and led development on enterprise B2B portals handling thousands of API payloads per hour.
              I bring the same rigor to system design, CI/CD, and infrastructure as I do to the code itself.
            </p>

            {/* Quick stats */}
            <div className="grid grid-cols-3 gap-6 mb-8">
              {[
                { number: '4+', label: 'Years Experience' },
                { number: '3', label: 'Cloud Certifications' },
                { number: '99.9%', label: 'Platform Uptime' },
              ].map((stat, i) => (
                <motion.div
                  key={stat.label}
                  initial={{ opacity: 0, y: 20 }}
                  animate={isVisible ? { opacity: 1, y: 0 } : {}}
                  transition={{ delay: 0.5 + i * 0.1 }}
                  className="text-center"
                >
                  <div className="text-3xl font-bold gradient-text">{stat.number}</div>
                  <div className="text-sm text-gray-500 mt-1">{stat.label}</div>
                </motion.div>
              ))}
            </div>

            <div className="flex gap-4">
              <a
                href="#contact"
                className="px-6 py-3 rounded-full bg-gradient-to-r from-cyan-500 to-violet-500 text-white font-medium hover:shadow-lg hover:shadow-cyan-500/25 transition-all duration-300 hover:scale-105"
              >
                Let's Connect
              </a>
              <a
                href={personalInfo.github}
                target="_blank"
                rel="noopener noreferrer"
                className="px-6 py-3 rounded-full glass glass-hover text-white font-medium"
              >
                GitHub
              </a>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
}
